// Minimal reader for the DASH manifest Meta ships inline on video posts
// (`video_dash_manifest` in the api/v1 media-info payload).
//
// React Native has no DOMParser, and pulling in an XML library for one field is
// not worth it — these manifests are machine-generated by Meta and their shape is
// stable, so the tags are matched directly. Verified August 2026 against a live
// Threads manifest:
//
//   <MPD ...><Period ...>
//     <AdaptationSet id="0" contentType="video" ...>
//       <Representation id="...v" bandwidth="203348" codecs="vp09.00.30.08..."
//                       mimeType="video/mp4" ...><BaseURL>…</BaseURL>…</Representation>
//       … 7 more video renditions, up to the original resolution …
//     </AdaptationSet>
//     <AdaptationSet id="1" contentType="audio" ...>
//       <Representation id="...a" bandwidth="62303" codecs="mp4a.40.5"
//                       mimeType="audio/mp4" audioSamplingRate="44100">
//         <BaseURL>…</BaseURL><SegmentBase indexRange="824-939">…</SegmentBase>
//       </Representation>
//     </AdaptationSet>
//   </Period></MPD>
//
// The AUDIO side feeds "Save as Audio". The VIDEO side is VP9: the default download
// still comes from the muxed H.264 `video_versions`, but the largest video
// representation is exposed as `MediaItem.originalVideo` so the opt-in "original
// quality" preference can mux it with the audio stream through FFmpeg (which, unlike
// Android's MediaMuxer, carries VP9 in MP4 reliably). See docs/MAINTENANCE.md §9/§18.

/** One `<Representation>` inside an `<AdaptationSet>`. */
interface DashRepresentation {
  url: string;
  bandwidth: number;
  codecs: string | null;
  width: number | null;
  height: number | null;
}

/**
 * Decodes the XML entities Meta escapes inside `<BaseURL>`.
 *
 * ⚠️ This is not cosmetic. The URLs carry query strings, so every `&` arrives as
 * `&amp;` — a signed URL with 11 of them answers **403** until they are decoded.
 * (A browser's DOMParser does this implicitly, which is exactly why a devtools probe
 * of the same manifest succeeds while the app's regex-parsed URL fails.)
 */
function decodeXmlEntities(value: string): string {
  return value
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_match, code: string) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_match, code: string) => String.fromCharCode(parseInt(code, 16)))
    // &amp; last: decoding it earlier would let "&amp;lt;" turn into "<".
    .replace(/&amp;/g, '&');
}

function numberAttribute(tag: string, name: string): number | null {
  const raw = attribute(tag, name);
  if (raw == null) return null;
  const value = Number(raw);
  return Number.isFinite(value) && value > 0 ? value : null;
}

function attribute(tag: string, name: string): string | null {
  // \b guards against `width` matching inside `bandwidth`.
  const match = tag.match(new RegExp(`\\b${name}="([^"]*)"`));
  return match ? match[1] : null;
}

/** Splits out each `<AdaptationSet …>…</AdaptationSet>` block. */
function adaptationSets(manifest: string): string[] {
  const blocks: string[] = [];
  let index = manifest.indexOf('<AdaptationSet');
  while (index !== -1) {
    const end = manifest.indexOf('</AdaptationSet>', index);
    if (end === -1) break;
    blocks.push(manifest.slice(index, end));
    index = manifest.indexOf('<AdaptationSet', end);
  }
  return blocks;
}

function representations(block: string): DashRepresentation[] {
  const reps: DashRepresentation[] = [];
  let index = block.indexOf('<Representation');
  while (index !== -1) {
    const end = block.indexOf('</Representation>', index);
    const slice = block.slice(index, end === -1 ? undefined : end);
    const openTagEnd = slice.indexOf('>');
    const openTag = openTagEnd === -1 ? slice : slice.slice(0, openTagEnd);

    const baseUrl = slice.match(/<BaseURL>([^<]+)<\/BaseURL>/);
    if (baseUrl) {
      reps.push({
        url: decodeXmlEntities(baseUrl[1].trim()),
        bandwidth: Number(attribute(openTag, 'bandwidth') ?? 0),
        codecs: attribute(openTag, 'codecs'),
        width: numberAttribute(openTag, 'width'),
        height: numberAttribute(openTag, 'height'),
      });
    }

    if (end === -1) break;
    index = block.indexOf('<Representation', end);
  }
  return reps;
}

/**
 * Highest-bandwidth audio-only stream in the manifest, or null.
 *
 * The URL is a whole self-contained fragmented MP4 — a plain GET returns
 * `ftyp + moov + sidx + moof/mdat…`, no range-driven segment assembly needed
 * (verified against a live manifest: 105,100 bytes for 62.3kbps × 13.374s).
 * Downloading it instead of the full video and stripping the audio track cuts a
 * reel's audio download by well over 10x.
 */
export function pickDashAudioUrl(manifest: unknown): string | null {
  if (typeof manifest !== 'string' || manifest.length === 0) return null;

  let best: DashRepresentation | null = null;
  for (const block of adaptationSets(manifest)) {
    const openTagEnd = block.indexOf('>');
    const openTag = openTagEnd === -1 ? block : block.slice(0, openTagEnd);
    const contentType = attribute(openTag, 'contentType');

    for (const rep of representations(block)) {
      // Trust contentType when present, else fall back to the representation's own
      // codecs string (mp4a = AAC).
      const isAudio =
        contentType === 'audio' || (contentType == null && /mp4a/i.test(rep.codecs ?? ''));
      if (!isAudio) continue;
      if (!best || rep.bandwidth > best.bandwidth) best = rep;
    }
  }

  return best ? best.url : null;
}

/** The largest video-only representation in the manifest, or null. */
export function pickDashVideo(manifest: unknown): {
  url: string;
  width: number | null;
  height: number | null;
  codecs: string | null;
  bandwidth: number | null;
} | null {
  if (typeof manifest !== 'string' || manifest.length === 0) return null;

  let best: DashRepresentation | null = null;
  for (const block of adaptationSets(manifest)) {
    const openTagEnd = block.indexOf('>');
    const openTag = openTagEnd === -1 ? block : block.slice(0, openTagEnd);
    const contentType = attribute(openTag, 'contentType');

    for (const rep of representations(block)) {
      const isVideo =
        contentType === 'video' ||
        (contentType == null && /^(vp0?9|avc|hev|hvc|av01)/i.test(rep.codecs ?? ''));
      if (!isVideo) continue;
      if (!best) {
        best = rep;
        continue;
      }
      // Rank by pixel count, then bandwidth — the manifest lists several bitrates at
      // one resolution and only the top rung is the original.
      const bestArea = (best.width ?? 0) * (best.height ?? 0);
      const area = (rep.width ?? 0) * (rep.height ?? 0);
      if (area > bestArea || (area === bestArea && rep.bandwidth > best.bandwidth)) best = rep;
    }
  }

  if (!best) return null;
  return {
    url: best.url,
    width: best.width,
    height: best.height,
    codecs: best.codecs,
    bandwidth: best.bandwidth || null,
  };
}
